def assemble_all_metrics(exp_dir):
    """Assemble all_metrics.json from per-gen metrics.json if needed."""
    all_path = os.path.join(exp_dir, "all_metrics.json")
    if os.path.exists(all_path):
        with open(all_path) as f:
            return json.load(f)

    metrics = []
    gen_idx = 0
    while True:
        gen_dir = os.path.join(exp_dir, f"gen_{gen_idx}")
        mpath = os.path.join(gen_dir, "metrics.json")
        if not os.path.exists(mpath):
            break
        with open(mpath) as f:
            m = json.load(f)
        m["generation"] = gen_idx
        metrics.append(m)
        gen_idx += 1

    if not metrics:
        return None
    return sorted(metrics, key=lambda x: x["generation"])


def compute_drift(metrics_list):
    result = {}
